//! XS-hosted compartment mapper for `endor run <entry.js>`.
//!
//! [`map_entry_point`] evaluates the `endor_run_mapper.js` bundle
//! (generated by `packages/daemon/scripts/bundle-endor-run-mapper-xs.mjs`)
//! in a short-lived XS machine. The bundle runs `@endo/compartment-mapper`
//! over the entry module and reports each archive file through the
//! `endorRunWriteFile(path, bytes)` host function, which forwards it to the
//! caller's sink. The mapper machine never executes the application: the
//! caller runs the resulting archive in a fresh machine.

use crate::ffi::*;
use crate::worker_io::{arg_str, read_typed_array_bytes};
use crate::{
    ensure_shared_cluster, eval_wrapped, register_host_powers, worker_io, JsValue, Machine,
    XsnapError, NATIVE_TEXT_CODEC, WORKER_CREATION,
};
use std::cell::RefCell;
use std::path::Path;

/// The bundled compartment mapper. Installs
/// `globalThis.endorRunMapEntryPoint(absolutePath)`.
pub const ENDOR_RUN_MAPPER: &str = include_str!("endor_run_mapper.js");

/// Receives each archive file the mapper produces, as an
/// archive-relative `/`-separated path and its bytes.
pub type FileSink<'a> = dyn FnMut(&str, &[u8]) -> std::io::Result<()> + 'a;

/// State shared with the host functions during one mapping run.
struct MapperRun {
    /// The caller's sink, lifetime-erased; valid only while
    /// [`map_entry_point`] is on the stack.
    sink: *mut FileSink<'static>,
    error: Option<String>,
    finished: bool,
}

thread_local! {
    static MAPPER_RUN: RefCell<Option<MapperRun>> = const { RefCell::new(None) };
}

/// `endorRunWriteFile(path, bytes)` — hand one archive file to the sink.
unsafe extern "C" fn host_endor_run_write_file(the: *mut XsMachine) {
    let path = arg_str(the, 0);
    let bytes = read_typed_array_bytes(the, (*the).frame.sub(2)).unwrap_or_default();
    MAPPER_RUN.with(|run| {
        let mut run = run.borrow_mut();
        let Some(run) = run.as_mut() else { return };
        if run.error.is_some() {
            return;
        }
        if let Err(e) = (*run.sink)(&path, &bytes) {
            run.error = Some(format!("cannot store {path}: {e}"));
        }
    });
}

/// `endorRunMapped()` — the mapping promise fulfilled.
unsafe extern "C" fn host_endor_run_mapped(_the: *mut XsMachine) {
    MAPPER_RUN.with(|run| {
        if let Some(run) = run.borrow_mut().as_mut() {
            run.finished = true;
        }
    });
}

/// `endorRunMapFailed(message)` — the mapping promise rejected.
unsafe extern "C" fn host_endor_run_map_failed(the: *mut XsMachine) {
    let message = arg_str(the, 0);
    MAPPER_RUN.with(|run| {
        if let Some(run) = run.borrow_mut().as_mut() {
            run.error.get_or_insert(message);
            run.finished = true;
        }
    });
}

/// Map the application whose entry module is `entry_path` and pass every
/// file of its archive (`compartment-map.json` first, then each captured
/// module source) to `sink`.
///
/// The entry path must be absolute. Returns an error if the mapper fails
/// (for example, an unresolvable import), if the sink fails, or if the
/// mapper never settles.
pub fn map_entry_point(entry_path: &Path, sink: &mut FileSink<'_>) -> Result<(), XsnapError> {
    let entry = entry_path.to_str().ok_or_else(|| {
        XsnapError::Io(format!("entry path is not UTF-8: {}", entry_path.display()))
    })?;
    if !entry_path.is_absolute() {
        return Err(XsnapError::Io(format!(
            "entry path is not absolute: {entry}"
        )));
    }

    ensure_shared_cluster();
    let machine = Machine::new(&WORKER_CREATION, "endor[map]")
        .ok_or_else(|| XsnapError::MachineInit("failed to create XS machine".to_string()))?;
    machine.register_worker_io();
    let powers = register_host_powers(&machine);
    machine.define_function("print", worker_io::host_trace, 1);
    machine.define_function("endorRunWriteFile", host_endor_run_write_file, 2);
    machine.define_function("endorRunMapped", host_endor_run_mapped, 0);
    machine.define_function("endorRunMapFailed", host_endor_run_map_failed, 1);

    // SAFETY: the pointer is cleared below before `sink` goes out of scope,
    // and host functions only run while this machine runs on this thread.
    let sink: *mut FileSink<'static> = unsafe { std::mem::transmute(sink as *mut FileSink<'_>) };
    MAPPER_RUN.with(|run| {
        *run.borrow_mut() = Some(MapperRun {
            sink,
            error: None,
            finished: false,
        });
    });

    let result = run_mapper(&machine, entry);

    let run = MAPPER_RUN.with(|run| run.borrow_mut().take());
    drop(machine);
    // SAFETY: allocated by `register_host_powers`; the machine that held
    // it is gone.
    unsafe { drop(Box::from_raw(powers)) };

    result?;
    match run {
        Some(MapperRun {
            error: Some(message),
            ..
        }) => Err(XsnapError::Archive(format!(
            "compartment mapper failed for {entry}: {message}"
        ))),
        Some(MapperRun { finished: true, .. }) => Ok(()),
        _ => Err(XsnapError::Archive(format!(
            "compartment mapper did not settle for {entry}"
        ))),
    }
}

fn run_mapper(machine: &Machine, entry: &str) -> Result<(), XsnapError> {
    // No `POLYFILLS`: its `harden` would make the bundle's SES lockdown
    // refuse to run.
    machine
        .eval(NATIVE_TEXT_CODEC)
        .ok_or_else(|| XsnapError::Bootstrap("text codec installation failed".to_string()))?;
    if !eval_wrapped(machine, ENDOR_RUN_MAPPER, "endor[map]/bundle") {
        return Err(XsnapError::Bootstrap(
            "compartment mapper bundle evaluation failed".to_string(),
        ));
    }
    let entry_literal = serde_json::to_string(entry)
        .map_err(|e| XsnapError::Io(format!("cannot encode entry path: {e}")))?;
    let invocation = format!(
        "endorRunMapEntryPoint({entry_literal}).then(\
            () => endorRunMapped(), \
            e => endorRunMapFailed(String((e && e.stack) || e))); \
         undefined"
    );
    match machine.eval(&invocation) {
        Some(JsValue::Undefined) | Some(_) => {}
        None => {
            return Err(XsnapError::Bootstrap(
                "compartment mapper invocation threw".to_string(),
            ))
        }
    }
    machine.quiesce();
    Ok(())
}
